<?php require '../includes/config.php'; require '../includes/layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$email=strtolower(trim($_POST['email']));$stmt=$conn->prepare('SELECT id,full_name,email,password_hash,role,department_id FROM users WHERE email=? LIMIT 1');$stmt->bind_param('s',$email);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();if($user&&password_verify($_POST['password'],$user['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'name'=>$user['full_name'],'role'=>$user['role'],'department_id'=>$user['department_id']];if($user['role']==='student')redirect('student/index.php');if($user['role']==='admin')redirect('admin/index.php');redirect('department/index.php');}$error='Invalid email or password.';}
